# -*- coding: utf-8 -*-
"""Installer v2 Tes Psikologi SIPSI 100 item. Nama baru agar tidak tertukar dengan pemasang lama."""
from pathlib import Path
from datetime import datetime
import base64
import py_compile
import re
import shutil
import sys

TARGET = Path("sipsi_mod.py")
PATCH_B64 = ""

if not TARGET.is_file():
    raise SystemExit("ERROR: sipsi_mod.py tidak ditemukan. Jalankan script ini dari folder proyek SIMPATIK.")
source = TARGET.read_text(encoding="utf-8")
required_routes = (
    "def psikologi_index(",
    "def psikologi_mulai(",
    "def psikologi_ujian(",
    "def psikologi_hasil(",
    "def psikologi_riwayat(",
)
present_routes = [marker for marker in required_routes if marker in source]
if all(marker in source for marker in required_routes) and "PSIKOLOGI_100_ITEMS" in source:
    raise SystemExit("SEMUA rute Tes Psikologi sudah ditemukan. Tidak ada perubahan dibuat.")
if present_routes or "PSIKOLOGI_100_ITEMS" in source:
    raise SystemExit(
        "TERDETEKSI kode Tes Psikologi yang tidak lengkap: " + ", ".join(present_routes or ["PSIKOLOGI_100_ITEMS"]) +
        ". File tidak diubah. Kirim hasil Select-String agar dapat diperbaiki tanpa duplikasi."
    )
match = re.search(r"(?m)^def init_sipsi\(", source)
if not match:
    raise SystemExit("ERROR: def init_sipsi tidak ditemukan. File tidak diubah.")

# Temukan dashboard SIPSI dan sisipkan kartu baru, tanpa mengubah kartu lama.
idx = source.find("def index():")
if idx < 0 or idx > match.start():
    raise SystemExit("ERROR: fungsi dashboard index() tidak ditemukan sebelum init_sipsi. File tidak diubah.")
next_route = source.find("@sipsi_bp.route(\"/mulai\"", idx)
if next_route < 0:
    next_route = source.find("def mulai(", idx)
if next_route < 0 or next_route > match.start():
    raise SystemExit("ERROR: batas bagian dashboard tidak ditemukan. File tidak diubah.")
dash = source[idx:next_route]
anchor = '<div class="action-grid">'
if anchor not in dash:
    raise SystemExit('ERROR: bagian action-grid dashboard tidak ditemukan. File tidak diubah.')
card = """<a class=\"action-card\" href=\"{url_for('sipsi.psikologi_index')}\">
        <div class=\"ico\" style=\"background:linear-gradient(135deg,#ea580c,#f59e0b)\"><i class=\"fas fa-brain\"></i></div>
        <div class=\"t\">Tes Psikologi</div>
        <div class=\"d\">Kuesioner refleksi 100 soal pilihan A–E</div>
      </a>
      """
# `body` is an f-string in the existing index() function, so this expression will be evaluated there.
dash = dash.replace(anchor, anchor + "\n      " + card, 1)
source = source[:idx] + dash + source[next_route:]
# Recompute insertion point after dashboard insertion.
match = re.search(r"(?m)^def init_sipsi\(", source)
if not match:
    raise SystemExit("ERROR: init_sipsi hilang saat menyiapkan perubahan. File tidak diubah.")
patch = base64.b64decode(PATCH_B64).decode("utf-8")
# Validasi payload sebelum menyentuh file asli.
if "PSIKOLOGI_100_ITEMS = [" not in patch or patch.count("@sipsi_bp.route(\"/psikologi") != 5:
    raise SystemExit("ERROR: payload pemasang tidak lengkap; sipsi_mod.py tidak diubah.")
source = source[:match.start()] + patch + "\n\n" + source[match.start():]

backup = TARGET.with_name("sipsi_mod_backup_psikologi_" + datetime.now().strftime("%Y%m%d_%H%M%S") + ".py")
shutil.copy2(TARGET, backup)
try:
    TARGET.write_text(source, encoding="utf-8", newline="\n")
    py_compile.compile(str(TARGET), doraise=True)
except Exception as exc:
    shutil.copy2(backup, TARGET)
    print("GAGAL: perubahan dibatalkan dan sipsi_mod.py dipulihkan dari backup.")
    print("Backup:", backup)
    raise SystemExit(str(exc))

# Verifikasi hitungan item di modul setelah disisipkan.
if source.count("('ach',") < 1 or "PSIKOLOGI_100_ITEMS" not in source:
    shutil.copy2(backup, TARGET)
    raise SystemExit("GAGAL verifikasi pascapemasangan; file asli dipulihkan.")
print("BERHASIL: Tes Psikologi 100 item dipasang di sipsi_mod.py")
print("Backup sumber:", backup.name)
print("Sintaks Python: OK")
print("Tes lama tidak diganti. Kartu Tes Psikologi ditambahkan pada dashboard SIPSI.")
print("Berikutnya jalankan: python app.py")
print("Lalu buka http://127.0.0.1:5001/sipsi dan pilih 'Tes Psikologi'.")
